INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','492','Rateio centros de custos sem apontamento - Melhoria Processo','Não informado','','Pendente','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2024-12-17T12:48:05-03:00','Triagem','Dados do formulário Categoria 1) Título : REABERTURA CHAMADO FECHADO DEVIDO S4 - SE - 213445 - Rateio centros de custos sem apontamento - Melhoria Processo 2) Categoria : Projeto > Estudo de viabilidade 3) Urgência : Baixa Entidade Descrição 4) Descreva sua solicitação : Rateio centros de custos sem apontamento Atualmente temos um processo de rateio para destinação dos custos daqueles centros de custos que não possuem direcionamento por meio de apontamentos de atividade (direcionamento direto onde foi utilizado o serviço), e todos os meses necessitamos realizar os ajustes e parametrizações dos ciclos de rateio, atualmente forma manual, passível de erros, e que nos demanda mais tempo para parametrização no sistema. Com base nisso solicito a criação de um Cockpit, que possibilite a informação de emissores de custos seja eles individuais ou coletivos a nível de núcleo, todas as classes de custos a serem consideradas na execução do rateio (que compõem só débitos do centro de custo), todos os receptores sejam individuais ou grupo também a nível de núcleo e o percentual/ valor que vai para cada receptor. A princípio a solução será centralizada entre centros de custos que vão para projetos com base no peso de cada cultura, a nível de PEP de acordo com a área do talhão, mas podemos ter situação em que teremos centro de custo enviando para outro centro de custo. Quando for PEP o sistema buscar na base do PS, os projetos ativos das culturas principais, e a área, fazer o cálculo do peso e distribuição dos custos por meio de um lançamento em classe secundário a nível de emissor e talhão, simulando a alocação de custo via rateio. Para atender nossa demanda pode ser consolidação um valor estático do total de custo do emissor para o receptor na hora do rateio nos atender. Mas se tiver como fazer uma alocação semelhante atividade de custos indiretos, onde gere confirmação a nível de talhão (talhão em que tem plantio, desconsiderando sede e talhões com status de encerrado) e no campo quantidade informar os Hectares do PEP, onde a definição do peso feita via KP26, de modo que seja executado semelhante a tarifa. São duas ideias que temos para atender a demanda. Anexo 5) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":492,"title":"Rateio centros de custos sem apontamento - Melhoria Processo","objective":"Dados do formulário Categoria 1) Título : REABERTURA CHAMADO FECHADO DEVIDO S4 - SE - 213445 - Rateio centros de custos sem apontamento - Melhoria Processo 2) Categoria : Projeto > Estudo de viabilidade 3) Urgência : Baixa Entidade Descrição 4) Descreva sua solicitação : Rateio centros de custos sem apontamento Atualmente temos um processo de rateio para destinação dos custos daqueles centros de custos que não possuem direcionamento por meio de apontamentos de atividade (direcionamento direto onde foi utilizado o serviço), e todos os meses necessitamos realizar os ajustes e parametrizações dos ciclos de rateio, atualmente forma manual, passível de erros, e que nos demanda mais tempo para parametrização no sistema. Com base nisso solicito a criação de um Cockpit, que possibilite a informação de emissores de custos seja eles individuais ou coletivos a nível de núcleo, todas as classes de custos a serem consideradas na execução do rateio (que compõem só débitos do centro de custo), todos os receptores sejam individuais ou grupo também a nível de núcleo e o percentual/ valor que vai para cada receptor. A princípio a solução será centralizada entre centros de custos que vão para projetos com base no peso de cada cultura, a nível de PEP de acordo com a área do talhão, mas podemos ter situação em que teremos centro de custo enviando para outro centro de custo. Quando for PEP o sistema buscar na base do PS, os projetos ativos das culturas principais, e a área, fazer o cálculo do peso e distribuição dos custos por meio de um lançamento em classe secundário a nível de emissor e talhão, simulando a alocação de custo via rateio. Para atender nossa demanda pode ser consolidação um valor estático do total de custo do emissor para o receptor na hora do rateio nos atender. Mas se tiver como fazer uma alocação semelhante atividade de custos indiretos, onde gere confirmação a nível de talhão (talhão em que tem plantio, desconsiderando sede e talhões com status de encerrado) e no campo quantidade informar os Hectares do PEP, onde a definição do peso feita via KP26, de modo que seja executado semelhante a tarifa. São duas ideias que temos para atender a demanda. Anexo 5) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Pendente","statusCode":4,"requester":"","requesterArea":"Não informado","openingDate":"2024-12-17T12:48:05-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
