INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','502','Relatório para analise da variação de preço - Substituição ao resultado do ledger (CKMLCP)','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2024-12-17T14:04:23-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Relatório para analise da variação de preço - Substituição ao resultado do ledger (CKMLCP) 2) Categoria : Projeto > Estudo de viabilidade 3) Urgência : Baixa Entidade Descrição 4) Descreva sua solicitação : Criar um relatório para que seja possivel analisar o preço de todos os materiais reavaliados pelo Ledger, e tambem a varição de todos os custos unitários dos materiais movimentados pelo grupo Bom Jesus. Verificar as movimentações e alocações dos valores se ficaram corretas. Desta forma assegurando que o preço vigente do material va transitar de forma correta dentro do mês em questão, e fornecer informações para tomadas de decisões. Anexo 5) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":502,"title":"Relatório para analise da variação de preço - Substituição ao resultado do ledger (CKMLCP)","objective":"Dados do formulário Categoria 1) Título : Relatório para analise da variação de preço - Substituição ao resultado do ledger (CKMLCP) 2) Categoria : Projeto > Estudo de viabilidade 3) Urgência : Baixa Entidade Descrição 4) Descreva sua solicitação : Criar um relatório para que seja possivel analisar o preço de todos os materiais reavaliados pelo Ledger, e tambem a varição de todos os custos unitários dos materiais movimentados pelo grupo Bom Jesus. Verificar as movimentações e alocações dos valores se ficaram corretas. Desta forma assegurando que o preço vigente do material va transitar de forma correta dentro do mês em questão, e fornecer informações para tomadas de decisões. Anexo 5) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2024-12-17T14:04:23-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
