INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','572','Implantação SAP ARIBA','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2024-12-18T12:34:48-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Implantação SAP ARIBA 2) Categoria : Projeto > Estudo de viabilidade 3) Urgência : Média Entidade Descrição 4) Descreva sua solicitação : Gostaríamos de iniciar o processo de implantação do sistema SAP Ariba em nossa empresa. Trata-se de um sistema SRM focado em cotações e leilões externos, que oferece diversas melhorias no processo de compras. Atualmente, utilizamos o sistema SRM da empresa Paradigma, mas devido a desafios enfrentados com esta plataforma, acreditamos ser viável considerar a migração para o SAP Ariba. Esperamos que o SAP Ariba proporcione uma performance superior, maior flexibilidade nas customizações, melhores ferramentas de análise de dados e integrações mais eficientes, uma vez que se trata de uma solução fornecida pela própria SAP. Aguardamos um retorno de sua parte, e se possível gostaríamos de agendar uma call para alinharmos detalhes antes de qualquer tomada de decisão sobre fazer essa implantação. Segue em anexo duas propostas de implantação fornecidas pela empresa Procurement Compass. Anexo 5) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":572,"title":"Implantação SAP ARIBA","objective":"Dados do formulário Categoria 1) Título : Implantação SAP ARIBA 2) Categoria : Projeto > Estudo de viabilidade 3) Urgência : Média Entidade Descrição 4) Descreva sua solicitação : Gostaríamos de iniciar o processo de implantação do sistema SAP Ariba em nossa empresa. Trata-se de um sistema SRM focado em cotações e leilões externos, que oferece diversas melhorias no processo de compras. Atualmente, utilizamos o sistema SRM da empresa Paradigma, mas devido a desafios enfrentados com esta plataforma, acreditamos ser viável considerar a migração para o SAP Ariba. Esperamos que o SAP Ariba proporcione uma performance superior, maior flexibilidade nas customizações, melhores ferramentas de análise de dados e integrações mais eficientes, uma vez que se trata de uma solução fornecida pela própria SAP. Aguardamos um retorno de sua parte, e se possível gostaríamos de agendar uma call para alinharmos detalhes antes de qualquer tomada de decisão sobre fazer essa implantação. Segue em anexo duas propostas de implantação fornecidas pela empresa Procurement Compass. Anexo 5) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2024-12-18T12:34:48-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
