ity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2025-02-11T06:37:58-03:00","priority":"2","type":"2"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
