INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','7467','Remessa para controle de pneus recapados','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2025-03-14T15:03:13-03:00','Encerrada no GLPI','Prezados (a) Temos um cenario que foi definido a estrategia de pneus rodoviarios linha pesada Bom Jesus Agro. Será utilizado as operações e boas práticas da "transportadora" O material ficara estocado na transportes reduzindo a demanda do CD, as trocas seram realizadas na trasportadora e gestão do das recapagens. Ponto observado é; Padronização da utlização e gestão das recapagens. Sabendo que o pneu enviado para recagaem fornecedore emiti uma NF de serviço. Hoje nao temos controle de estoque desses item, o ideal é estocar esse pneu para ter o controle o custo da recapagem agregar no estoque e o equipamento que utlizar esse pneu (s) obsorver esse custo.','','','',0,0,'Médio',false,'{"id":7467,"title":"Remessa para controle de pneus recapados","objective":"Prezados (a) Temos um cenario que foi definido a estrategia de pneus rodoviarios linha pesada Bom Jesus Agro. Será utilizado as operações e boas práticas da \"transportadora\" O material ficara estocado na transportes reduzindo a demanda do CD, as trocas seram realizadas na trasportadora e gestão do das recapagens. Ponto observado é; Padronização da utlização e gestão das recapagens. Sabendo que o pneu enviado para recagaem fornecedore emiti uma NF de serviço. Hoje nao temos controle de estoque desses item, o ideal é estocar esse pneu para ter o controle o custo da recapagem agregar no estoque e o equipamento que utlizar esse pneu (s) obsorver esse custo.","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2025-03-14T15:03:13-03:00","priority":"2","type":"2"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
