INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','32308','Sistemas - Implementações/Melhorias Sistemas Jurídicos - Contencioso','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2025-10-13T05:39:13-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Implementações/Melhorias Sistemas Jurídicos - Contencioso 2) Selecione o Sistema : Microsoft 365 3) Categoria : Sistemas > Melhoria 4) Urgência : Alta Entidades 5) Ramal : 5684 Descrição 6) Descrição : Bom dia, prezados! Atualmente, o setor Jurídico — especificamente a equipe do Contencioso — faz uso de alguns sistemas voltados à otimização e ao controle dos processos do Grupo Bom Jesus. Os sistemas atualmente utilizados são: RR Jurídico , T-Legal e JusBrasil . No entanto, identificamos a necessidade de aprimoramentos para potencializar a eficiência dos serviços prestados. Encaminharei, em anexo, dois arquivos detalhando os sistemas que utilizamos, bem como o principal desafio enfrentado no momento, relacionado ao sistema T-Legal . Diante das informações apresentadas, solicitamos o apoio de V.S.as quanto à possibilidade de implementação de um novo sistema que atenda melhor às demandas da equipe ou, alternativamente, de aperfeiçoamento dos sistemas atualmente em uso . Ademais, sugerimos a realização de uma pesquisa sobre o sistema Alerte , o qual apresenta funcionalidades similares às do sistema T-Legal. Anexo 7) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":32308,"title":"Sistemas - Implementações/Melhorias Sistemas Jurídicos - Contencioso","objective":"Dados do formulário Categoria 1) Título : Implementações/Melhorias Sistemas Jurídicos - Contencioso 2) Selecione o Sistema : Microsoft 365 3) Categoria : Sistemas > Melhoria 4) Urgência : Alta Entidades 5) Ramal : 5684 Descrição 6) Descrição : Bom dia, prezados! Atualmente, o setor Jurídico — especificamente a equipe do Contencioso — faz uso de alguns sistemas voltados à otimização e ao controle dos processos do Grupo Bom Jesus. Os sistemas atualmente utilizados são: RR Jurídico , T-Legal e JusBrasil . No entanto, identificamos a necessidade de aprimoramentos para potencializar a eficiência dos serviços prestados. Encaminharei, em anexo, dois arquivos detalhando os sistemas que utilizamos, bem como o principal desafio enfrentado no momento, relacionado ao sistema T-Legal . Diante das informações apresentadas, solicitamos o apoio de V.S.as quanto à possibilidade de implementação de um novo sistema que atenda melhor às demandas da equipe ou, alternativamente, de aperfeiçoamento dos sistemas atualmente em uso . Ademais, sugerimos a realização de uma pesquisa sobre o sistema Alerte , o qual apresenta funcionalidades similares às do sistema T-Legal. Anexo 7) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2025-10-13T05:39:13-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
