INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','36503','Implementação - Integração ERP Sênior x SAP','Não informado','','Pendente','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2025-10-22T10:55:11-03:00','Triagem','Dados do formulário Categoria 1) Título : Solicitação de Implementação de Integração entre ERP Sênior e SAP 2) Selecione o Sistema : Senior 3) Categoria : Sistemas > Automação de Processo/RPA 4) Urgência : Alta Entidades 5) Ramal : 5605 Descrição 6) Descrição : Dar continuidade ao chamado nº 13422 anteriormente aberto, estava em andamento e foi fechado sem concluir. Considerando o grande volume de lançamentos financeiros realizados manualmente na transação FB60 e Pedido do SAP , venho solicitar a implementação da integração entre o ERP Sênior e o SAP , com o objetivo de automatizar e otimizar o processamento dos lançamentos referentes a: Folha de pagamento Diárias Férias Rescisão 13º salário Adiantamento salarial INSS FGTS GFD - Guia FGTS digital Contribuição sindical IRRF Unimed Ressalto que todos os lançamentos são realizados por empresa, filial, centro de lucro e centro de custo, o que reforça a necessidade de uma integração estruturada que garanta a correta alocação das despesas. O objetivo dessa integração é que possamos: minimizar o tempo despendido nos lançamentos manuais, redução de erros operacionais, maior precisão e conformidade nas informações financeiras, melhoria no controle interno, otimização do fluxo entre as DP, Contas a Pagar e Contabilidade O sistema Sênior Rubi já disponibiliza uma aba específica de Integração ERP , que, ao que tudo indica, possui o objetivo de realizar o envio automatizado dos dados financeiros ao SAP. Dessa forma, os lançamentos financeiros seriam gerados automaticamente no SAP, com a alocação correta por empresa, filial, centro de lucro e centro de custo, eliminando retrabalhos e reduzindo riscos. Anexo 7) Insira anexo (se necessário) : Nenhum documento anexado','','','',0,0,'Médio',false,'{"id":36503,"title":"Implementação - Integração ERP Sênior x SAP","objective":"Dados do formulário Categoria 1) Título : Solicitação de Implementação de Integração entre ERP Sênior e SAP 2) Selecione o Sistema : Senior 3) Categoria : Sistemas > Automação de Processo/RPA 4) Urgência : Alta Entidades 5) Ramal : 5605 Descrição 6) Descrição : Dar continuidade ao chamado nº 13422 anteriormente aberto, estava em andamento e foi fechado sem concluir. Considerando o grande volume de lançamentos financeiros realizados manualmente na transação FB60 e Pedido do SAP , venho solicitar a implementação da integração entre o ERP Sênior e o SAP , com o objetivo de automatizar e otimizar o processamento dos lançamentos referentes a: Folha de pagamento Diárias Férias Rescisão 13º salário Adiantamento salarial INSS FGTS GFD - Guia FGTS digital Contribuição sindical IRRF Unimed Ressalto que todos os lançamentos são realizados por empresa, filial, centro de lucro e centro de custo, o que reforça a necessidade de uma integração estruturada que garanta a correta alocação das despesas. O objetivo dessa integração é que possamos: minimizar o tempo despendido nos lançamentos manuais, redução de erros operacionais, maior precisão e conformidade nas informações financeiras, melhoria no controle interno, otimização do fluxo entre as DP, Contas a Pagar e Contabilidade O sistema Sênior Rubi já disponibiliza uma aba específica de Integração ERP , que, ao que tudo indica, possui o objetivo de realizar o envio automatizado dos dados financeiros ao SAP. Dessa forma, os lançamentos financeiros seriam gerados automaticamente no SAP, com a alocação correta por empresa, filial, centro de lucro e centro de custo, eliminando retrabalhos e reduzindo riscos. Anexo 7) Insira anexo (se necessário) : Nenhum documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Pendente","statusCode":4,"requester":"","requesterArea":"Não informado","openingDate":"2025-10-22T10:55:11-03:00","priority":"2","type":"2"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
