INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','36737','Automação RPA - Atualização Automática de Documentos de Medição','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2025-10-23T05:04:41-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Criação de RPA - Atualização da posição do contador para equipamentos parados 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Automação de Processo/RPA 4) Urgência : Média Entidades 5) Ramal : 5739 Descrição 6) Descrição : Os planos de manutenção do SAP são sempre baseados em data, mesmo criando ele para programar com base em um contador de hodometro e horimetro, ele utiliza os apontamentos do contador e a atividade anual estipulada pra calcular uma previsão de data em que o ciclo do plano irá vencer. Se o equipamento ficar parado e não tiver mais apontamentos de contador, o plano mantém aquela data calculada na previsão e ao atingir essa data a ordem é aberta mesmo que o horímetro não tenha atingido o ciclo. Analisar se é possível criar um RPA que verifique se houve apontamento de contador há menos de uma semana. Se não houver, ele faz um novo apontamento com a mesma posição de contador. Assim o plano faz um novo cálculo de previsão de data, fazendo com que a ordem não abra mais cedo que o contador. Segue print do cálculo feito pelo SAP para o plano 19032. Com o último apontamento de 827h feito no dia 21.10.2025 a data prevista era de 23.12.2025. Após ser feito novo apontamento pela IK11 com mesmo contador de 827h mas na data de 23.10.205 a data prevista foi alterada para 25.12.2025. Anexo 7) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":36737,"title":"Automação RPA - 