INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','38306','Sistemas - Sistemas voltados à gestão, controle e segurança de certificados digitais.','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2025-10-28T13:07:36-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Sistemas voltados à gestão, controle e segurança de certificados digitais. 2) Selecione o Sistema : Microsoft 365 3) Categoria : Sistemas > Melhoria 4) Urgência : Alta Entidades 5) Ramal : 5684 Descrição 6) Descrição : Prezados, boa tarde! Considerando as demandas do setor jurídico e a necessidade de aprimorar a segurança e o controle no uso de certificados digitais, solicita-se a avaliação e possível implementação de um sistema de gestão, controle e segurança de certificados digitais. O setor jurídico lida diariamente com documentos sensíveis, peticionamentos eletrônicos e assinaturas digitais com validade jurídica, o que exige rigor no controle de acesso e uso dos certificados. A ausência de um sistema centralizado aumenta o risco de uso indevido, extravio, duplicidade de acesso e comprometimento da validade jurídica de atos processuais. Diante desse cenário, sugere-se a análise dos sistemas Whom Doc9 e Presto | Gestão Inteligente de Senhas e Certificados Digitais, que oferecem soluções voltadas à segurança e governança digital. Breve resumo dos sistemas e benefícios: 1. Presto | Gestão Inteligente de Senhas e Certificados Digitais Centraliza e automatiza a gestão de certificados e senhas corporativas; Permite controle de acessos, rastreabilidade e registro de uso; Garante conformidade com a LGPD e com as normas da ICP-Brasil; Emite alertas de vencimento e renovação, evitando bloqueios; Eleva a segurança da informação e reduz riscos de uso indevido. 2. Whom Doc9 | Gestão e Armazenamento Seguro de Certificados Digitais Realiza guarda em nuvem segura dos certificados digitais; Utiliza criptografia avançada e autenticação multifator; Elimina a necessidade de tokens físicos, ampliando a mobilidade; Possibilita gestão por perfis, auditoria e histórico de acessos; Reduz falhas operacionais e otimiza o uso de assinaturas digitais. Pontos relevantes em comum: Aumento da segurança e governança digital; Conformidade normativa e mitigação de riscos cibernéticos; Centralização e controle dos certificados; Maior eficiência e rastreabilidade de acessos. Na oportunidade, encaminho em anexo o arquivo com a proposta encaminhada pela Whom Doc9. Anexo 7) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":38306,"title":"Sistemas - Sistemas voltados à gestão, controle e segurança de certificados digitais.","objective":"Dados do formulário Categoria 1) Título : Sistemas voltados à gestão, controle e segurança de certificados digitais. 2) Selecione o Sistema : Microsoft 365 3) Categoria : Sistemas > Melhoria 4) Urgência : Alta Entidades 5) Ramal : 5684 Descrição 6) Descrição : Prezados, boa tarde! Considerando as demandas do setor jurídico e a necessidade de aprimorar a segurança e o controle no uso de certificados digitais, solicita-se a avaliação e possível implementação de um sistema de gestão, controle e segurança de certificados digitais. O setor jurídico lida diariamente com documentos sensíveis, peticionamentos eletrônicos e assinaturas digitais com validade jurídica, o que exige rigor no controle de acesso e uso dos certificados. A ausência de um sistema centralizado aumenta o risco de uso indevido, extravio, duplicidade de acesso e comprometimento da validade jurídica de atos processuais. Diante desse cenário, sugere-se a análise dos sistemas Whom Doc9 e Presto | Gestão Inteligente de Senhas e Certificados Digitais, que oferecem soluções voltadas à segurança e governança digital. Breve resumo dos sistemas e benefícios: 1. Presto | Gestão Inteligente de Senhas e Certificados Digitais Centraliza e automatiza a gestão de certificados e senhas corporativas; Permite controle de acessos, rastreabilidade e registro de uso; Garante conformidade com a LGPD e com as normas da ICP-Brasil; Emite alertas de vencimento e renovação, evitando bloqueios; Eleva a segurança da informação e reduz riscos de uso indevido. 2. Whom Doc9 | Gestão e Armazenamento Seguro de Certificados Digitais Realiza guarda em nuvem segura dos certificados digitais; Utiliza criptografia avançada e autenticação multifator; Elimina a necessidade de tokens físicos, ampliando a mobilidade; Possibilita gestão por perfis, auditoria e histórico de acessos; Reduz falhas operacionais e otimiza o uso de assinaturas digitais. Pontos relevantes em comum: Aumento da segurança e governança digital; Conformidade normativa e mitigação de riscos cibernéticos; Centralização e controle dos certificados; Maior eficiência e rastreabilidade de acessos. Na oportunidade, encaminho em anexo o arquivo com a proposta encaminhada pela Whom Doc9. Anexo 7) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2025-10-28T13:07:36-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
