INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','52575','Sistemas - Concentrar as informações de Imoveis Rurais Proprios no SAP','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2025-12-17T14:21:36-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Concentrar as informações de Imoveis Rurais Proprios no SAP 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Sustentação 4) Urgência : Média Entidades 5) Ramal : 5832 Descrição 6) Descrição : Olá, Com o objetivo de otimizar, controlar e conciliar as informações referentes aos imóveis rurais do Grupo Bom Jesus, o departamento fiscal solicita a criação de uma transação no SAP (no mesmo modelo utilizado na criação do Portal de Notas Fiscais de Serviços – ZNFSE), exclusiva para centralizar todas as funções e informações pertinentes a cada departamento envolvido para gestão de Imóveis Rurais. A transação consistirá no desenvolvimento de “módulos”, que contenham os dados referentes as propriedades, com informações pertinentes a cada departamento (pág. 04 anexo). Possibilitando a emissão e relatórios, conciliações, demonstrativo e pré preenchimento da DITR com simulação de cálculo de acordo com as informações preenchidas. Anexo, segue solicitação detalhada para melhor entendimento da demanda solicitada. Dúvidas, estamos à disposição Chamado havia sido aberto no SE 264804 - Gestão de Imóveis Rurais – ITR 2023 - Aberto em 24/05/2023 (Encerrado para aguardar a migração do ECC para S/4) - (Será avaliado. 07.03.2025) Anexo 7) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":52575,"title":"Sistemas - Concentrar as informações de Imoveis Rurais Proprios no SAP","objective":"Dados do formulário Categoria 1) Título : Concentrar as informações de Imoveis Rurais Proprios no SAP 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Sustentação 4) Urgência : Média Entidades 5) Ramal : 5832 Descrição 6) Descrição : Olá, Com o objetivo de otimizar, controlar e conciliar as informações referentes aos imóveis rurais do Grupo Bom Jesus, o departamento fiscal solicita a criação de uma transação no SAP (no mesmo modelo utilizado na criação do Portal de Notas Fiscais de Serviços – ZNFSE), exclusiva para centralizar todas as funções e informações pertinentes a cada departamento envolvido para gestão de Imóveis Rurais. A transação consistirá no desenvolvimento de “módulos”, que contenham os dados referentes as propriedades, com informações pertinentes a cada departamento (pág. 04 anexo). Possibilitando a emissão e relatórios, conciliações, demonstrativo e pré preenchimento da DITR com simulação de cálculo de acordo com as informações preenchidas. Anexo, segue solicitação detalhada para melhor entendimento da demanda solicitada. Dúvidas, estamos à disposição Chamado havia sido aberto no SE 264804 - Gestão de Imóveis Rurais – ITR 2023 - Aberto em 24/05/2023 (Encerrado para aguardar a migração do ECC para S/4) - (Será avaliado. 07.03.2025) Anexo 7) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2025-12-17T14:21:36-03:00","priority":"3","type":"2"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
