INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','52813','Centralização C.C Aeronaves Agrícolas','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2025-12-18T12:02:52-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Centralização C.C Aeronaves Agrícolas - Sequência chamado t_28229 2) Categoria : Projeto > Estudo de viabilidade 3) Urgência : Alta Entidade Descrição 4) Descreva sua solicitação : Olá, Conforme reunião realizada no dia de hoje 18/12/2025, foi realizado que a demanda fosse aberta como projeto para estudo de viabilidade, em continuação ao chamado t_28229 aberto em 30/09/2025. Precisamos que seja centralizado o totalizador de custos das aeronaves em um único centro de custo, sendo eles: salários, depreciação, manutenções, combustível, seguro, serviço tercerizado e outros se houver. A ideia é criar um centro de custo por aeronave, para que tenhamos uma tarifa única por aeronave, onde ela realizar o trabalho/apontamento o custo acumulado para esse centro de custo deverá ser distribuídos formando assim o custo de cada projeto agrícola. Abaixo definições preliminares para essa melhoria: Centralização dos imobilizados das aeronaves na matriz; Tarifa única por aeronave; Depreciação proporcional à área sobrevoada; Orçamento anual máquina a máquina elaborado pelo corporativo; Criação de centro de custo para a frota da aeronave, seguindo modelo dos caminhões BJAT. Já foram envolvidas as áreas: custos, fiscal, imobilizado, administrativo, controle agrícola, planejamento de produção. Para que a iniciativa não tenha impactos para operação, solicitamos que seja criado distruição de custei a partir do apontamento agrícola, ou seja, no SAP a partir do momento em que for identificado o apontamento de x horas, x h.a, executado pelo equipamento x, o custo seja interamente distribuído para o C.C da aeronave, utilizando o C.C da unidade somente como centro transitório. Att. Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado','','','',0,0,'Médio',false,'{"id":52813,"title":"Centralização C.C Aeronaves Agrícolas","objective":"Dados do formulário Categoria 1) Título : Centralização C.C Aeronaves Agrícolas - Sequência chamado t_28229 2) Categoria : Projeto > Estudo de viabilidade 3) Urgência : Alta Entidade Descrição 4) Descreva sua solicitação : Olá, Conforme reunião realizada no dia de hoje 18/12/2025, foi realizado que a demanda fosse aberta como projeto para estudo de viabilidade, em continuação ao chamado t_28229 aberto em 30/09/2025. Precisamos que seja centralizado o totalizador de custos das aeronaves em um único centro de custo, sendo eles: salários, depreciação, manutenções, combustível, seguro, serviço tercerizado e outros se houver. A ideia é criar um centro de custo por aeronave, para que tenhamos uma tarifa única por aeronave, onde ela realizar o trabalho/apontamento o custo acumulado para esse centro de custo deverá ser distribuídos formando assim o custo de cada projeto agrícola. Abaixo definições preliminares para essa melhoria: Centralização dos imobilizados das aeronaves na matriz; Tarifa única por aeronave; Depreciação proporcional à área sobrevoada; Orçamento anual máquina a máquina elaborado pelo corporativo; Criação de centro de custo para a frota da aeronave, seguindo modelo dos caminhões BJAT. Já foram envolvidas as áreas: custos, fiscal, imobilizado, administrativo, controle agrícola, planejamento de produção. Para que a iniciativa não tenha impactos para operação, solicitamos que seja criado distruição de custei a partir do apontamento agrícola, ou seja, no SAP a partir do momento em que for identificado o apontamento de x horas, x h.a, executado pelo equipamento x, o custo seja interamente distribuído para o C.C da aeronave, utilizando o C.C da unidade somente como centro transitório. Att. Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2025-12-18T12:02:52-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
