INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','66171','Implementação - Software para Gestão de Controles Internos','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-02-04T08:15:27-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Automatização de Software para Gestão de Controles Internos 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Alta Entidade Descrição 4) Descreva sua solicitação : Boa tarde, Solicito a análise para a automatização de um software dedicado à área de Controles Internos, com foco em gestão de riscos, testes de controles, governança e geração de relatórios gerenciais. A necessidade da ferramenta está alinhada à evolução da maturidade dos controles internos da companhia, ao fortalecimento da governança e à adoção de boas práticas de mercado, visando maior eficiência, padronização, rastreabilidade e confiabilidade das informações. 1. Objetivo da Ferramenta Implantar uma solução tecnológica que permita a gestão integrada de riscos e controles internos, possibilitando: Centralização das informações; Automatização de processos manuais; Acompanhamento estruturado dos testes de controles; Visão gerencial e executiva por meio de dashboards e relatórios; Suporte às decisões e o cumprimento de requisitos. 2. Principais Funcionalidades Esperadas (Melhores Práticas de Mercado) 2.1 Gestão de Riscos Cadastro e manutenção da Matriz de Riscos Corporativa; Classificação por processos, áreas, unidades e ciclos; Avaliação de riscos inerentes e residuais; Metodologia configurável (probabilidade, impacto, apetite a risco, riscos prioritários); Associação de riscos aos respectivos controles; Histórico de alterações e versionamento da matriz; Registro de planos de ação, responsáveis e prazos. 2.2 Gestão de Controles Internos Cadastro estruturado dos controles (preventivos/detectivos); Vinculação dos controles aos riscos e processos; Definição de frequência, responsáveis e evidências; Avaliação de desenho e efetividade operacional; Workflow de aprovação e validação dos controles; Registro de deficiências, falhas e recomendações; Classificação de deficiências (leve, moderada, relevante, material – se aplicável). 2.3 Testes de Controles Planejamento anual de testes; Execução dos testes diretamente na ferramenta; Upload e guarda de evidências; Trilhas de auditoria (quem testou, quando, resultado); Registro de conclusões e follow-up automático; Relatórios de status dos testes (realizado, pendente, em atraso). 2.4 Ciclos e Planejamento Anual Configuração de ciclos anuais de controles internos ; Planejamento por exercício (escopo, prioridades, riscos críticos); Acompanhamento do andamento do ciclo; Comparativo entre exercícios (evolução de maturidade). 2.5 Relatórios Gerenciais e Dashboards Dashboards executivos (KPIs de riscos e controles); Relatórios por área, processo ou ciclo; Indicadores de: Riscos críticos; Controles inefetivos; Planos de ação em atraso; Grau de aderência aos controles; Exportação de relatórios (PDF, Excel, PowerPoint); Visão executiva para diretoria e comitês. 2.6 Governança, Compliance e Segurança Controle de acessos por perfil (segregação de funções); Logs e trilhas de auditoria; Armazenamento seguro das informações; Aderência a boas práticas de GRC (COSO, ISO 31000); Possibilidade de integração futura com outros sistemas corporativos. 3. Benefícios Esperados Aumento da eficiência da área de Controles Internos; Padronização dos processos; Maior confiabilidade e tempestividade das informações; Melhoria na comunicação com diretoria e áreas de negócio; Suporte à tomada de decisão estratégica. 4. Prazo e Criticidade Solicito que a análise de viabilidade considere como premissa obrigatória que a solução esteja totalmente implantada, configurada, homologada e pronta para uso no início do segundo semestre do ano, com data alvo de entrada em produção em 01/07/2026 . Dessa forma, a avaliação deverá priorizar soluções já consolidadas no mercado, com baixo tempo de implementação, possibilidade de parametrização e rápida adoção pela área de Controles Internos, garantindo o suporte ao ciclo anual, aos testes de controles e aos relatórios gerenciais do segundo semestre. 5. Próximos Passos Esperados Avaliação de soluções disponíveis no mercado (GRC / Controles Internos); Análise de custos, benefícios e esforço de implementação; Avaliação de requisitos técnicos e de segurança da informação; Definição de cronograma preliminar de implantação. Fico à disposição para esclarecimentos adicionais e para participar das etapas de levantamento de requisitos e demonstrações técnicas, caso necessário. Atenciosamente, Aliny Maria Lourenço Coordenação de Controles Internos Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado','','','',0,0,'Médio',false,'{"id":66171,"title":"Implementação - Software para Gestão de Controles Internos","objective":"Dados do formulário Categoria 1) Título : Automatização de Software para Gestão de Controles Internos 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Alta Entidade Descrição 4) Descreva sua solicitação : Boa tarde, Solicito a análise para a automatização de um software dedicado à área de Controles Internos, com foco em gestão de riscos, testes de controles, governança e geração de relatórios gerenciais. A necessidade da ferramenta está alinhada à evolução da maturidade dos controles internos da companhia, ao fortalecimento da governança e à adoção de boas práticas de mercado, visando maior eficiência, padronização, rastreabilidade e confiabilidade das informações. 1. Objetivo da Ferramenta Implantar uma solução tecnológica que permita a gestão integrada de riscos e controles internos, possibilitando: Centralização das informações; Automatização de processos manuais; Acompanhamento estruturado dos testes de controles; Visão gerencial e executiva por meio de dashboards e relatórios; Suporte às decisões e o cumprimento de requisitos. 2. Principais Funcionalidades Esperadas (Melhores Práticas de Mercado) 2.1 Gestão de Riscos Cadastro e manutenção da Matriz de Riscos Corporativa; Classificação por processos, áreas, unidades e ciclos; Avaliação de riscos inerentes e residuais; Metodologia configurável (probabilidade, impacto, apetite a risco, riscos prioritários); Associação de riscos aos respectivos controles; Histórico de alterações e versionamento da matriz; Registro de planos de ação, responsáveis e prazos. 2.2 Gestão de Controles Internos Cadastro estruturado dos controles (preventivos/detectivos); Vinculação dos controles aos riscos e processos; Definição de frequência, responsáveis e evidências; Avaliação de desenho e efetividade operacional; Workflow de aprovação e validação dos controles; Registro de deficiências, falhas e recomendações; Classificação de deficiências (leve, moderada, relevante, material – se aplicável). 2.3 Testes de Controles Planejamento anual de testes; Execução dos testes diretamente na ferramenta; Upload e guarda de evidências; Trilhas de auditoria (quem testou, quando, resultado); Registro de conclusões e follow-up automático; Relatórios de status dos testes (realizado, pendente, em atraso). 2.4 Ciclos e Planejamento Anual Configuração de ciclos anuais de controles internos ; Planejamento por exercício (escopo, prioridades, riscos críticos); Acompanhamento do andamento do ciclo; Comparativo entre exercícios (evolução de maturidade). 2.5 Relatórios Gerenciais e Dashboards Dashboards executivos (KPIs de riscos e controles); Relatórios por área, processo ou ciclo; Indicadores de: Riscos críticos; Controles inefetivos; Planos de ação em atraso; Grau de aderência aos controles; Exportação de relatórios (PDF, Excel, PowerPoint); Visão executiva para diretoria e comitês. 2.6 Governança, Compliance e Segurança Controle de acessos por perfil (segregação de funções); Logs e trilhas de auditoria; Armazenamento seguro das informações; Aderência a boas práticas de GRC (COSO, ISO 31000); Possibilidade de integração futura com outros sistemas corporativos. 3. Benefícios Esperados Aumento da eficiência da área de Controles Internos; Padronização dos processos; Maior confiabilidade e tempestividade das informações; Melhoria na comunicação com diretoria e áreas de negócio; Suporte à tomada de decisão estratégica. 4. Prazo e Criticidade Solicito que a análise de viabilidade considere como premissa obrigatória que a solução esteja totalmente implantada, configurada, homologada e pronta para uso no início do segundo semestre do ano, com data alvo de entrada em produção em 01/07/2026 . Dessa forma, a avaliação deverá priorizar soluções já consolidadas no mercado, com baixo tempo de implementação, possibilidade de parametrização e rápida adoção pela área de Controles Internos, garantindo o suporte ao ciclo anual, aos testes de controles e aos relatórios gerenciais do segundo semestre. 5. Próximos Passos Esperados Avaliação de soluções disponíveis no mercado (GRC / Controles Internos); Análise de custos, benefícios e esforço de implementação; Avaliação de requisitos técnicos e de segurança da informação; Definição de cronograma preliminar de implantação. Fico à disposição para esclarecimentos adicionais e para participar das etapas de levantamento de requisitos e demonstrações técnicas, caso necessário. Atenciosamente, Aliny Maria Lourenço Coordenação de Controles Internos Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2026-02-04T08:15:27-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
