INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','77779','Implementação - Custeio Pecuária','Não informado','','Pendente','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-03-16T05:02:59-03:00','Triagem','Dados do formulário Categoria 1) Título : Estruturação custeio pecuária 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Média Entidade Descrição 4) Descreva sua solicitação : Objetivo: Implantar o processo de custeio das etapas de cria, recria e engorda de bovinos no Grupo Bom Jesus, considerando que atualmente esse controle é realizado de forma manual nas quatro unidades pecuárias: PEC1 Mirandópolis, PEC2 Branca, PEC3 Nova Viena e PEC4 Umbuzeiro. Necessidade Controlar o custo das matrizes durante a gestação, conforme o período de inseminação, para posteriormente agregar aos bezerros que nascerem: • Inseminação; • Baixa de alimentação (sal, pastagem, silagem, etc); • Vacinas; • Medicamentos. Registrar via processo no sistema o nascimento (entrada de produção); Registrar a baixa, caso ocorra a morte do bezerro; Controlar os custos das matrizes durante a amamentação para direcionar aos bezerros (fêmea ou macho); Realizar a evolução das idades bovinas, ao atingir as idades estabelecidas; Se o bezerro for classificado como matriz ou reprodutor, transferir para ativo imobilizado; Quando o estoque estiver disponível para venda, realizar a transferência para estoque acabado. Chamado já aberto anteriormente: 326228 Anexo os processos. Anexo 5) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":77779,"title":"Implementação - Custeio Pecuária","objective":"Dados do formulário Categoria 1) Título : Estruturação custeio pecuária 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Média Entidade Descrição 4) Descreva sua solicitação : Objetivo: Implantar o processo de custeio das etapas de cria, recria e engorda de bovinos no Grupo Bom Jesus, considerando que atualmente esse controle é realizado de forma manual nas quatro unidades pecuárias: PEC1 Mirandópolis, PEC2 Branca, PEC3 Nova Viena e PEC4 Umbuzeiro. Necessidade Controlar o custo das matrizes durante a gestação, conforme o período de inseminação, para posteriormente agregar aos bezerros que nascerem: • Inseminação; • Baixa de alimentação (sal, pastagem, silagem, etc); • Vacinas; • Medicamentos. Registrar via processo no sistema o nascimento (entrada de produção); Registrar a baixa, caso ocorra a morte do bezerro; Controlar os custos das matrizes durante a amamentação para direcionar aos bezerros (fêmea ou macho); Realizar a evolução das idades bovinas, ao atingir as idades estabelecidas; Se o bezerro for classificado como matriz ou reprodutor, transferir para ativo imobilizado; Quando o estoque estiver disponível para venda, realizar a transferência para estoque acabado. Chamado já aberto anteriormente: 326228 Anexo os processos. Anexo 5) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Pendente","statusCode":4,"requester":"","requesterArea":"Não informado","openingDate":"2026-03-16T05:02:59-03:00","priority":"3","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
