INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','77997','Automação - Distribuição do Custo das Cantinas','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-03-16T10:55:02-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Distribuição do custo das cantinas 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Média Entidade Descrição 4) Descreva sua solicitação : Objetivo Automatizar e tornar mais precisa a distribuição dos custos das refeições nas cantinas, utilizando os registros de acesso dos colaboradores capturados pelas catracas e integrados ao SAP, garantindo a correta apropriação dos custos aos respectivos centros de custo. Necessidade No Grupo, nas unidades que possuem catraca de controle de acesso nas cantinas, a distribuição dos custos deverá ser realizada com base nos registros de acesso às refeições integrados ao SAP. Dessa forma, os dados capturados pela catraca, conforme utilização pelos colaboradores, servirão como base de rateio, permitindo a apropriação dos custos das refeições de forma mais precisa aos respectivos centros de custo vinculados a cada colaborador. Hoje os rateios das Cantinas têm sua distribuição parametrizada no Ciclo I tendo como emissores os custos dos centros de custos das cantinas e como centros de custos receptores, é distribuído de acordo com a base do RH, com os funcionários que possuem status “Trabalhando” no mês que está sendo distribuídos os custos. Mensalmente antes de rodar a transação KSU5 para distribuir os custos da Cantina, é necessário parametrizar por empresa na transação KSU2 a base receptora. Segue exemplo: Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado','','','',0,0,'Médio',false,'{"id":77997,"title":"Automação - Distribuição do Custo das Cantinas","objective":"Dados do formulário Categoria 1) Título : Distribuição do custo das cantinas 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Média Entidade Descrição 4) Descreva sua solicitação : Objetivo Automatizar e tornar mais precisa a distribuição dos custos das refeições nas cantinas, utilizando os registros de acesso dos colaboradores capturados pelas catracas e integrados ao SAP, garantindo a correta apropriação dos custos aos respectivos centros de custo. Necessidade No Grupo, nas unidades que possuem catraca de controle de acesso nas cantinas, a distribuição dos custos deverá ser realizada com base nos registros de acesso às refeições integrados ao SAP. Dessa forma, os dados capturados pela catraca, conforme utilização pelos colaboradores, servirão como base de rateio, permitindo a apropriação dos custos das refeições de forma mais precisa aos respectivos centros de custo vinculados a cada colaborador. Hoje os rateios das Cantinas têm sua distribuição parametrizada no Ciclo I tendo como emissores os custos dos centros de custos das cantinas e como centros de custos receptores, é distribuído de acordo com a base do RH, com os funcionários que possuem status “Trabalhando” no mês que está sendo distribuídos os custos. Mensalmente antes de rodar a transação KSU5 para distribuir os custos da Cantina, é necessário parametrizar por empresa na transação KSU2 a base receptora. Segue exemplo: Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2026-03-16T10:55:02-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`sour