INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','78049','Implementação - Distribuição dos custos dos caminhões das fazendas','Não informado','','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-03-16T12:20:32-03:00','Encerrada no GLPI','Dados do formulário Categoria 1) Título : Distribuição dos custos dos caminhões das fazendas 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Média Entidade Descrição 4) Descreva sua solicitação : Objetivo Garantir que os custos relacionados às operações dos caminhões das fazendas sejam distribuídos corretamente conforme o tipo de operação realizada, direcionando o custo para o destino apropriado via sistema. Necessidade Atualmente, a distribuição dos custos relacionados às operações dos caminhões das fazendas é realizada de forma manual, com base nas informações enviadas pelas unidades. Cada unidade informa como os custos devem ser distribuídos, de acordo com os Km rodados e o processo é realizado manualmente pelo departamento de custo. Esse modelo gera retrabalho, risco de inconsistências e dependência de controles paralelos, além de dificultar a rastreabilidade e padronização do processo entre as unidades. Dessa forma, há a necessidade de que a distribuição dos custos dos caminhões seja realizada de forma sistematizada, utilizando como base as informações registradas nas operações e nas viagens dos veículos. A proposta é que essa distribuição passe a ocorrer por meio de uma transação semelhante com a ZCO013, direcionando os custos para o destino correspondente à operação em que o serviço foi efetivamente prestado. A distribuição deverá considerar o tipo de operação realizada, garantindo que os custos sejam apropriados corretamente em estoque, despesas ou centros de custo, conforme a natureza da operação. Benefícios Esperados Padronização do processo de distribuição dos custos dos caminhões entre todas as unidades do grupo. Redução de atividades manuais, diminuindo retrabalho operacional do departamento de custos. Maior precisão na apropriação dos custos, direcionando corretamente para estoque, despesas ou centros de custo conforme o tipo de operação realizada. Redução do risco de inconsistências e erros decorrentes de controles paralelos e lançamentos manuais. Melhoria na rastreabilidade das informações, facilitando análises, conferências e auditorias. Melhor qualidade das informações gerenciais, apoiando análises de custo e tomada de decisão. Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado','','','',0,0,'Médio',false,'{"id":78049,"title":"Implementação - Distribuição dos custos dos caminhões das fazendas","objective":"Dados do formulário Categoria 1) Título : Distribuição dos custos dos caminhões das fazendas 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Média Entidade Descrição 4) Descreva sua solicitação : Objetivo Garantir que os custos relacionados às operações dos caminhões das fazendas sejam distribuídos corretamente conforme o tipo de operação realizada, direcionando o custo para o destino apropriado via sistema. Necessidade Atualmente, a distribuição dos custos relacionados às operações dos caminhões das fazendas é realizada de forma manual, com base nas informações enviadas pelas unidades. Cada unidade informa como os custos devem ser distribuídos, de acordo com os Km rodados e o processo é realizado manualmente pelo departamento de custo. Esse modelo gera retrabalho, risco de inconsistências e dependência de controles paralelos, além de dificultar a rastreabilidade e padronização do processo entre as unidades. Dessa forma, há a necessidade de que a distribuição dos custos dos caminhões seja realizada de forma sistematizada, utilizando como base as informações registradas nas operações e nas viagens dos veículos. A proposta é que essa distribuição passe a ocorrer por meio de uma transação semelhante com a ZCO013, direcionando os custos para o destino correspondente à operação em que o serviço foi efetivamente prestado. A distribuição deverá considerar o tipo de operação realizada, garantindo que os custos sejam apropriados corretamente em estoque, despesas ou centros de custo, conforme a natureza da operação. Benefícios Esperados Padronização do processo de distribuição dos custos dos caminhões entre todas as unidades do grupo. Redução de atividades manuais, diminuindo retrabalho operacional do departamento de custos. Maior precisão na apropriação dos custos, direcionando corretamente para estoque, despesas ou centros de custo conforme o tipo de operação realizada. Redução do risco de inconsistências e erros decorrentes de controles paralelos e lançamentos manuais. Melhoria na rastreabilidade das informações, facilitando análises, conferências e auditorias. Melhor qualidade das informações gerenciais, apoiando análises de custo e tomada de decisão. Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"","requesterArea":"Não informado","openingDate":"2026-03-16T12:20:32-03:00","priority":"2","type":"2"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
