INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','79305','Devolução de Transferência por desconto de classificação','Não informado','','Pendente','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-03-20T10:47:58-03:00','Triagem','Dados do formulário Categoria 1) Título : Parametrização - Devolução de Transferência por desconto de classificação 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Automação de Processo/RPA 4) Urgência : Média Entidades 5) Ramal : 5600 Descrição 6) Descrição : Melhoria no processo de devolução de volume por umidade e impurezas com automação da atividade no SAP. Atualmente, o processo existente atende a necessidade operacional, porém é realizado de forma manual pelo controle de estoque, o que não é o formato mais adequado, gerando riscos operacionais e retrabalho. Solicitamos avaliação, análise e desenvolvimento de melhorias no processo atual, com foco na automatização das rotinas operacionais e maior integração sistêmica no SAP. Durante reunião recente, foram identificadas limitações relevantes no sistema, especialmente relacionadas a: Tratamento de devoluções parciais, que atualmente não refletem corretamente os impactos nas ordens de produção; Ausência de amarrações completas entre documentos, como viagem, nota fiscal e ordem de produção, dificultando a rastreabilidade e a consistência das informações; Necessidade já apontada em análises anteriores, que indicavam a importância de desenvolvimento específico após a atualização do sistema. Além disso, foi destacada a necessidade de estruturar uma solução sistêmica que elimine intervenções manuais realizadas pela controladoria, aumentando a confiabilidade, a rastreabilidade e a eficiência do processo. Outro ponto crítico refere-se à apuração correta da rentabilidade da fazenda de origem do grão, considerando a necessidade de desconsiderar automaticamente fatores como impurezas e umidade no cálculo dos resultados. Dessa forma, solicitamos o apoio da área de TI para: Avaliação técnica das limitações atuais do SAP; Proposição de solução sistêmica (customização, desenvolvimento ou parametrização); Implementação de melhorias que garantam integração entre documentos, automatização do fluxo e maior confiabilidade das informações gerenciais e operacionais. Ficamos à disposição para detalhamento do processo e apoio no levantamento de requisitos. Anexo 7) Insira anexo (se necessário) : Nenhum documento anexado','','','',0,0,'Médio',false,'{"id":79305,"title":"Devolução de Transferência por desconto de classificação","objective":"Dados do formulário Categoria 1) Título : Parametrização - Devolução de Transferência por desconto de classificação 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Automação de Processo/RPA 4) Urgência : Média Entidades 5) Ramal : 5600 Descrição 6) Descrição : Melhoria no processo de devolução de volume por umidade e impurezas com automação da atividade no SAP. Atualmente, o processo existente atende a necessidade operacional, porém é realizado de forma manual pelo controle de estoque, o que não é o formato mais adequado, gerando riscos operacionais e retrabalho. Solicitamos avaliação, análise e desenvolvimento de melhorias no processo atual, com foco na automatização das rotinas operacionais e maior integração sistêmica no SAP. Durante reunião recente, foram identificadas limitações relevantes no sistema, especialmente relacionadas a: Tratamento de devoluções parciais, que atualmente não refletem corretamente os impactos nas ordens de produção; Ausência de amarrações completas entre documentos, como viagem, nota fiscal e ordem de produção, dificultando a rastreabilidade e a consistência das informações; Necessidade já apontada em análises anteriores, que