INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','79331','Sistemas - Centralização de Informações de Imóveis Rurais Próprios no SAP','Não informado','','Pendente','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-03-20T11:30:38-03:00','Triagem','Dados do formulário Categoria 1) Título : Centralização de Informações de Imóveis Rurais Próprios no SAP 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Sustentação 4) Urgência : Média Entidades 5) Ramal : 5832 Descrição 6) Descrição : Prezados, Com o objetivo de otimizar, centralizar, controlar e conciliar todas as informações relacionadas aos imóveis rurais próprios do Grupo Bom Jesus , solicitamos a criação de uma transação específica no SAP , nos mesmos moldes do portal já utilizado para Notas Fiscais de Serviço ( ZNFSE ). A proposta consiste em desenvolver uma área única dentro do SAP para concentrar todos os dados e funções necessárias à gestão dos imóveis rurais, com módulos estruturados por área, conforme detalhado no documento anexo. Essa transação permitirá: Centralização dos dados cadastrais de cada propriedade; Integração das informações utilizadas por vários departamento s Comparativos entre módulos (área, dados cadastrais, CAR, CCIR, ADA, Matrícula, NIRF, VTN, contabilidade etc.); Emissão de relatórios gerenciais e operacionais; Conciliações automáticas entre informações de diferentes origens; Geração de demonstrativos; Garantirá governança, rastreabilidade, padronização e redução de riscos fiscais, além de eliminar retrabalhos e facilitar auditorias e fiscalizações. Pré-preenchimento da DITR , com possibilidade de simulação do cálculo de acordo com os dados informados nos módulos. A necessidade desta solução já havia sido registrada anteriormente no chamado SE 264804 – Gestão de Imóveis Rurais – ITR 2023 , aberto em 24/05/2023 , que permaneceu pendente devido à migração do ECC para o S/4 e foi encerrado com previsão de reavaliação em 07/03/2025 , e abertura do chamado t_52575. Diante da consolidação do ambiente S/4 e da continuidade das demandas operacionais, solicitamos a retomada e priorização deste projeto. Anexo: Documento técnico detalhado para melhor entendimento da demanda. Ficamos à disposição para esclarecimentos, validações ou reuniões necessárias para alinhamento funcional e técnico. Anexo 7) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":79331,"title":"Sistemas - Centralização de Informações de Imóveis Rurais Próprios no SAP","objective":"Dados do formulário Categoria 1) Título : Centralização de Informações de Imóveis Rurais Próprios no SAP 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Sustentação 4) Urgência : Média Entidades 5) Ramal : 5832 Descrição 6) Descrição : Prezados, Com o objetivo de otimizar, centralizar, controlar e conciliar todas as informações relacionadas aos imóveis rurais próprios do Grupo Bom Jesus , solicitamos a criação de uma transação específica no SAP , nos mesmos moldes do portal já utilizado para Notas Fiscais de Serviço ( ZNFSE ). A proposta consiste em desenvolver uma área única dentro do SAP para concentrar todos os dados e funções necessárias à gestão dos imóveis rurais, com módulos estruturados por área, conforme detalhado no documento anexo. Essa transação permitirá: Centralização dos dados cadastrais de cada propriedade; Integração das informações utilizadas por vários departamento s Comparativos entre módulos (área, dados cadastrais, CAR, CCIR, ADA, Matrícula, NIRF, VTN, contabilidade etc.); Emissão de relatórios gerenciais e operacionais; Conciliações automáticas entre informações de diferentes origens; Geração de demonstrativos; Garantirá governança, rastreabilidade, padronização e redução de riscos fiscais, além de eliminar retrabalhos e facilitar auditorias e fiscalizações. Pré-preenchimento da DITR , com possibilidade de simulação do cálculo de acordo com os dados informados nos módulos. A necessidade desta solução já havia sido registrada anteriormente no chamado SE 264804 – Gestão de Imóveis Rurais – ITR 2023 , aberto em 24/05/2023 , que permaneceu pendente devido à migração do ECC para o S/4 e foi encerrado com previsão de reavaliação em 07/03/2025 , e abertura do chamado t_52575. Diante da consolidação do ambiente S/4 e da continuidade das demandas operacionais, solicitamos a retomada e priorização deste projeto. Anexo: Documento técnico detalhado para melhor entendimento da demanda. Ficamos à disposição para esclarecimentos, validações ou reuniões necessárias para alinhamento funcional e técnico. Anexo 7) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Pendente","statusCode":4,"requester":"","requesterArea":"Não informado","openingDate":"2026-03-20T11:30:38-03:00","priority":"2","type":"2"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
