INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','83594','Sistemas - Solicitação de Melhoria Sistêmica – Distribuição de Custos das Aeronaves','Não informado','','Em atendimento','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-04-09T06:33:21-03:00','Triagem','Dados do formulário Categoria 1) Título : Solicitação de Melhoria Sistêmica – Distribuição de Custos das Aeronaves 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Melhoria 4) Urgência : Média Entidades 5) Ramal : 5644 Descrição 6) Descrição : Solicitação de Melhoria Sistêmica – Distribuição de Custos das Aeronaves 1. Objetivo O Grupo Bom Jesus possui atualmente 11 aeronaves agrícolas e 03 aeronaves executivas. Os custos relacionados à operação aérea são registrados em centros de custo específicos de aviação nas fazendas, contemplando: Custos fixos: salários de pilotos, contratos de prestação de serviços, depreciação e seguros; Custos variáveis: combustível, manutenção e demais insumos operacionais. Entretanto, cada modelo de aeronave apresenta características operacionais distintas, impactando diretamente seu custo por hora de voo e produtividade. Como exemplo: A diferença entre o Air Tractor AT-502B e o Embraer Ipanema EMB-202/203 reside no fato de o Air Tractor ser uma aeronave turboélice de maior porte e produtividade, enquanto o Ipanema é uma aeronave a pistão, com custos operacionais mais baixos, porém menor capacidade de carga. O AT-502B possui custo de aquisição e hora de voo significativamente mais elevados, compensados por maior produtividade por hectare. Atualmente, as horas de voo são registradas por meio de apontamentos em hectares aplicados, sendo essas informações utilizadas para compor as tarifas operacionais e realizar a distribuição dos custos registrados no centro de custo de aviação para os talhões atendidos. Contudo, na estrutura atual do SAP ERP , cada aeronave está vinculada a um único centro de custo por meio do centro de trabalho. Dessa forma: Os apontamentos realizados são direcionados automaticamente ao centro de custo de origem da aeronave; As ordens de serviço seguem a mesma lógica, independentemente do local real da operação. 2. Problema As aeronaves operam de forma itinerante entre as fazendas, não havendo alocação fixa por unidade produtiva. Em um mesmo período, uma aeronave pode atender diversas fazendas. No entanto, devido à limitação atual do sistema: Os custos permanecem concentrados apenas nos centros de custo onde as aeronaves estão cadastradas; Das aproximadamente 95 unidades agrícolas do grupo, cerca de 84 não recebem corretamente os custos das operações aéreas realizadas em suas áreas. 3. Impactos Identificados Essa limitação gera uma série de impactos relevantes: Concentração indevida de custos: As fazendas onde as aeronaves estão registradas absorvem integralmente custos que pertencem a outras unidades; Subavaliação de custos em outras fazendas: As unidades atendidas registram apenas custos parciais (ex.: combustível), sem refletir o custo total da operação; Distorção na formação de tarifas: A fragmentação entre custos e atividades inviabiliza o cálculo preciso do custo por hora/hectare; Inconsistência no custo de produção agrícola: Fazendas com aeronaves apresentam custos inflados, enquanto outras apresentam custos subestimados; Impacto na valorização de estoque: O custo acumulado na lavoura, utilizado para valorização do estoque após a colheita, sofre distorções; Comprometimento das análises gerenciais: Rentabilidade, margens e comparativos entre fazendas tornam-se inconsistentes; Impossibilidade operacional de ajuste: A Gerência de Produção já sinalizou que não é viável manter aeronaves fixas por fazenda. Além dos impactos operacionais, destacam-se pontos estruturais que reforçam a criticidade da demanda: Integridade e governança de dados: O modelo atual rompe o princípio de que o custo deve refletir o local onde ocorre a operação, prejudicando rastreabilidade, auditorias e confiabilidade das informações; Redução de controles manuais: A ausência de solução sistêmica incentiva rateios manuais e controles paralelos, aumentando risco de erro, retrabalho e perda de produtividade; Escalabilidade da operação: O modelo atual não acompanha a complexidade do grupo e tende a se agravar com o crescimento da operação; Aderência às boas práticas do SAP: O correto, dentro do SAP ERP , é que os custos sejam alocados com base no consumo real (atividade executada), e não pela posse do ativo; Impacto nos indicadores (KPIs): Indicadores como custo por hectare, eficiência operacional e margem por fazenda tornam-se inconsistentes, prejudicando comparações e análises; Risco de decisões estratégicas equivocadas: Informações distorcidas podem levar a conclusões incorretas sobre rentabilidade, eficiência e necessidade de investimentos; Desalinhamento entre áreas: A operação é dinâmica e compartilhada, enquanto o sistema está estruturado de forma fixa, gerando inconsistência entre prática e registro; Base comprometida para BI e automações: Qualquer iniciativa futura de análise de dados ou dashboards herdará distorções caso a base não seja corrigida. 4. Demanda de Melhoria Diante do exposto, solicita-se a estruturação de uma solução sistêmica que permita a distribuição adequada dos custos das aeronaves, garantindo: Que cada fazenda receba os custos proporcionais às atividades efetivamente realizadas; Que a alocação seja baseada em direcionadores reais (hectares aplicados, horas de voo, etc.); Que somente os centros/projetos que receberam serviços sejam onerados; Que seja possível mensurar o custo por atividade (ex.: aplicação aérea por hectare); Que não haja distorção nos resultados individuais das unidades; Que seja possível apurar corretamente o custo de produção agrícola, valorização de estoque e rentabilidade por fazenda. A melhoria proposta não se trata apenas de um ajuste operacional, mas de uma necessidade estratégica para garantir a integridade das informações gerenciais do grupo. Sua implementação permitirá: Maior confiabilidade dos dados; Redução de retrabalho e riscos operacionais; Melhor suporte à tomada de decisão; Alinhamento entre operação, controladoria e sistemas. Sem essa adequação, o grupo continuará sujeito a distorções relevantes que comprometem a visão real de seus resultados. Anexo 7) Insira anexo (se necessário) : Nenhum documento anexado','','','',0,0,'Médio',false,'{"id":83594,"title":"Sistemas - Solicitação de Melhoria Sistêmica – Distribuição de Custos das Aeronaves","objective":"Dados do formulário Categoria 1) Título : Solicitação de Melhoria Sistêmica – Distribuição de Custos das Aeronaves 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Melhoria 4) Urgência : Média Entidades 5) Ramal : 5644 Descrição 6) Descrição : Solicitação de Melhoria Sistêmica – Distribuição de Custos das Aeronaves 1. Objetivo O Grupo Bom Jesus possui atualmente 11 aeronaves agrícolas e 03 aeronaves executivas. Os custos relacionados à operação aérea são registrados em centros de custo específicos de aviação nas fazendas, contemplando: Custos fixos: salários de pilotos, contratos de prestação de serviços, depreciação e seguros; Custos variáveis: combustível, manutenção e demais insumos operacionais. Entretanto, cada modelo de aeronave apresenta características operacionais distintas, impactando diretamente seu custo por hora de voo e produtividade. Como exemplo: A diferença entre o Air Tractor AT-502B e o Embraer Ipanema EMB-202/203 reside no fato de o Air Tractor ser uma aeronave turboélice de maior porte e produtividade, enquanto o Ipanema é uma aeronave a pistão, com custos operacionais mais baixos, porém menor capacidade de carga. O AT-502B possui custo de aquisição e hora de voo significativamente mais elevados, compensados por maior produtividade por hectare. Atualmente, as horas de voo são registradas por meio de apontamentos em hectares aplicados, sendo essas informações utilizadas para compor as tarifas operacionais e realizar a distribuição dos custos registrados no centro de custo de aviação para os talhões atendidos. Contudo, na estrutura atual do SAP ERP , cada aeronave está vinculada a um único centro de custo por meio do centro de trabalho. Dessa forma: Os apontamentos realizados são direcionados automaticamente ao centro de custo de origem da aeronave; As ordens de serviço seguem a mesma lógica, independentemente do local real da operação. 2. Problema As aeronaves operam de forma itinerante entre as fazendas, não havendo alocação fixa por unidade produtiva. Em um mesmo período, uma aeronave pode atender diversas fazendas. No entanto, devido à limitação atual do sistema: Os custos permanecem concentrados apenas nos centros de custo onde as aeronaves estão cadastradas; Das aproximadamente 95 unidades agrícolas do grupo, cerca de 84 não recebem corretamente os custos das operações aéreas realizadas em suas áreas. 3. Impactos Identificados Essa limitação gera uma série de impactos relevantes: Concentração indevida de custos: As fazendas onde as aeronaves estão registradas absorvem integralmente custos que pertencem a outras unidades; Subavaliação de custos em outras fazendas: As unidades atendidas registram apenas custos parciais (ex.: combustível), sem refletir o custo total da operação; Distorção na formação de tarifas: A fragmentação entre custos e atividades inviabiliza o cálculo preciso do custo por hora/hectare; Inconsistência no custo de produção agrícola: Fazendas com aeronaves apresentam custos inflados, enquanto outras apresentam custos subestimados; Impacto na valorização de estoque: O custo acumulado na lavoura, utilizado para valorização do estoque após a colheita, sofre distorções; Comprometimento das análises gerenciais: Rentabilidade, margens e comparativos entre fazendas tornam-se inconsistentes; Impossibilidade operacional de ajuste: A Gerência de Produção já sinalizou que não é viável manter aeronaves fixas por fazenda. Além dos impactos operacionais, destacam-se pontos estruturais que reforçam a criticidade da demanda: Integridade e governança de dados: O modelo atual rompe o princípio de que o custo deve refletir o local onde ocorre a operação, prejudicando rastreabilidade, auditorias e confiabilidade das informações; Redução de controles manuais: A ausência de solução sistêmica incentiva rateios manuais e controles paralelos, aumentando risco de erro, retrabalho e perda de produtividade; Escalabilidade da operação: O modelo atual não acompanha a complexidade do grupo e tende a se agravar com o crescimento da operação; Aderência às boas práticas do SAP: O correto, dentro do SAP ERP , é que os custos sejam alocados com base no consumo real (atividade executada), e não pela posse do ativo; Impacto nos indicadores (KPIs): Indicadores como custo por hectare, eficiência operacional e margem por fazenda tornam-se inconsistentes, prejudicando comparações e análises; Risco de decisões estratégicas equivocadas: Informações distorcidas podem levar a conclusões incorretas sobre rentabilidade, eficiência e necessidade de investimentos; Desalinhamento entre áreas: A operação é dinâmica e compartilhada, enquanto o sistema está estruturado de forma fixa, gerando inconsistência entre prática e registro; Base comprometida para BI e automações: Qualquer iniciativa futura de análise de dados ou dashboards herdará distorções caso a base não seja corrigida. 4. Demanda de Melhoria Diante do exposto, solicita-se a estruturação de uma solução sistêmica que permita a distribuição adequada dos custos das aeronaves, garantindo: Que cada fazenda receba os custos proporcionais às atividades efetivamente realizadas; Que a alocação seja baseada em direcionadores reais (hectares aplicados, horas de voo, etc.); Que somente os centros/projetos que receberam serviços sejam onerados; Que seja possível mensurar o custo por atividade (ex.: aplicação aérea por hectare); Que não haja distorção nos resultados individuais das unidades; Que seja possível apurar corretamente o custo de produção agrícola, valorização de estoque e rentabilidade por fazenda. A melhoria proposta não se trata apenas de um ajuste operacional, mas de uma necessidade estratégica para garantir a integridade das informações gerenciais do grupo. Sua implementação permitirá: Maior confiabilidade dos dados; Redução de retrabalho e riscos operacionais; Melhor suporte à tomada de decisão; Alinhamento entre operação, controladoria e sistemas. Sem essa adequação, o grupo continuará sujeito a distorções relevantes que comprometem a visão real de seus resultados. Anexo 7) Insira anexo (se necessário) : Nenhum documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Em atendimento","statusCode":2,"requester":"","requesterArea":"Não informado","openingDate":"2026-04-09T06:33:21-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
