INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','123507','Gestão de Remuneração Variável','Não informado','','Pendente','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-09-18T05:04:40-03:00','Triagem','Dados do formulário Categoria 1) Título : Gestão de Remuneração Variável 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Baixa Entidade Descrição 4) Descreva sua solicitação : Objetivo do Projeto Implementar uma solução centralizada para Gestão de Remuneração Variável, visando automatizar os processos de cálculo, consolidação e apuração das premiações praticadas pelo Grupo Bom Jesus. Contexto Atual Atualmente, a empresa possui aproximadamente 10 a 15 modelos distintos de remuneração variável, cada um com regras, políticas de cálculo e públicos específicos. O processo é executado de forma manual, utilizando diversas planilhas recebidas de diferentes áreas e responsáveis. Após a consolidação das informações, os cálculos são realizados em Excel e posteriormente lançados na folha de pagamento. Esse modelo gera alta dependência de controles manuais, maior esforço operacional, risco de inconsistências nos cálculos e dificuldade na rastreabilidade das informações. Necessidade do Projeto Desenvolver ou implantar uma plataforma que permita centralizar e automatizar os fluxos relacionados à remuneração variável, contemplando: Cadastro e manutenção das políticas de premiação; Parametrização das regras de cálculo; Consolidação automática das informações oriundas das áreas envolvidas; Apuração e validação dos valores de premiação; Integração com a folha de pagamento; Rastreabilidade e auditoria dos cálculos realizados. Benefícios Esperados Redução de atividades manuais; Maior confiabilidade nos cálculos; Padronização dos processos; Ganho de produtividade das equipes envolvidas; Melhoria na governança e rastreabilidade das informações; Redução do risco de erros operacionais. Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado','','','',0,0,'Médio',false,'{"id":123507,"title":"Gestão de Remuneração Variável","objective":"Dados do formulário Categoria 1) Título : Gestão de Remuneração Variável 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Baixa Entidade Descrição 4) Descreva sua solicitação : Objetivo do Projeto Implementar uma solução centralizada para Gestão de Remuneração Variável, visando automatizar os processos de cálculo, consolidação e apuração das premiações praticadas pelo Grupo Bom Jesus. Contexto Atual Atualmente, a empresa possui aproximadamente 10 a 15 modelos distintos de remuneração variável, cada um com regras, políticas de cálculo e públicos específicos. O processo é executado de forma manual, utilizando diversas planilhas recebidas de diferentes áreas e responsáveis. Após a consolidação das informações, os cálculos são realizados em Excel e posteriormente lançados na folha de pagamento. Esse modelo gera alta dependência de controles manuais, maior esforço operacional, risco de inconsistências nos cálculos e dificuldade na rastreabilidade das informações. Necessidade do Projeto Desenvolver ou implantar uma plataforma que permita centralizar e automatizar os fluxos relacionados à remuneração variável, contemplando: Cadastro e manutenção das políticas de premiação; Parametrização das regras de cálculo; Consolidação automática das informações oriundas das áreas envolvidas; Apuração e validação dos valores de premiação; Integração com a folha de pagamento; Rastreabilidade e auditoria dos cálculos realizados. Benefícios Esperados Redução de atividades manuais; Maior confiabilidade nos cálculos; Padronização dos processos; Ganho de produtividade das equipes envolvidas; Melhoria na governança e rastreabilidade das informações; Redução do risco de erros operacionais. Anexo 5) Insira anexo (se necessário) : Nenhum documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Pendente","statusCode":4,"requester":"","requesterArea":"Não informado","openingDate":"2026-09-18T05:04:40-03:00","priority":"2","type":"1"}',1790801114892,1790801114892) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
